import React from 'react';
import classNames from 'classnames';

import './index.less';
import { Text } from '../../atoms';
import { AlignEnum, ColorNameEnum, SizeEnum, WeightEnum } from '../../types/enums';

export enum DetailListItemIconSide {
  RIGHT = 'RIGHT',
  LEFT = 'LEFT',
}

export type DetailsListItemType = {
  className?: string;
  offScreenText?: string;
  title?: string;
  text: string | React.ReactNode;
  icon?: string;
  iconSide?: DetailListItemIconSide;
};

const DetailsListItem = ({
  offScreenText,
  title,
  text,
  icon,
  className,
  iconSide = DetailListItemIconSide.RIGHT,
}: DetailsListItemType) => (
  <li className={classNames('details-list-item', className)}>
    {offScreenText && <h2 className="off-screen-text">{offScreenText}</h2>}
    {icon && (
      <Text
        className={classNames(
          `detail-icon ${icon}`,
          iconSide === DetailListItemIconSide.LEFT ? 'icon-left' : 'icon-right',
        )}
        colorName={ColorNameEnum.themeSecondary}
      />
    )}
    {title && (
      <Text
        size={SizeEnum['12px']}
        colorName={ColorNameEnum.ultraDark}
        align={AlignEnum.left}
        text={title}
        className={classNames('item-title', {
          'margin-left-30': iconSide === DetailListItemIconSide.LEFT,
        })}
      />
    )}
    <Text
      size={SizeEnum['14px']}
      colorName={ColorNameEnum.ultraDark}
      weight={WeightEnum.semibold}
      align={AlignEnum.left}
      text={typeof text === 'function' ? text() : text}
      className={classNames('margin-top-10 item-text', {
        'margin-left-30': iconSide === DetailListItemIconSide.LEFT,
      })}
    />
  </li>
);

export default DetailsListItem;
